package com.quincaisoft.identity.infrastructure;
import jakarta.persistence.*;import org.hibernate.annotations.DynamicUpdate;import java.util.*;import java.time.*;
@Entity @DynamicUpdate @Table(name="identity_change") @IdClass(MembershipChange.Key.class) public class MembershipChange {public record Key(UUID tenantId,UUID companyId,UUID id) implements java.io.Serializable{} @Id @Column(name="tenant_id")public UUID tenantId;@Id @Column(name="company_id")public UUID companyId;@Id public UUID id;@Column(name="branch_id")public UUID branchId;@Column(name="operation_id")public UUID operationId;@Column(name="target_actor")public UUID targetActor;@Column(name="requested_by")public UUID requestedBy;@Column(name="approved_by")public UUID approvedBy;@Column(name="approval_operation")public UUID approvalOperation;@Column(name="desired_role")public String desiredRole;@Column(name="desired_active")public boolean desiredActive;@Column(name="expected_epoch")public long expectedEpoch;public String reason;public String status;@Version public long version;@Column(name="created_at")public Instant createdAt;}